create table public.listing_fitments (
  id uuid default gen_random_uuid() not null,
  listing_id uuid not null,
  make text not null,
  model text not null,
  year_start integer,
  year_end integer,
  created_at timestamp with time zone default now() not null
);

alter table public.listing_fitments enable row level security;

-- Constraints
alter table public.listing_fitments add constraint listing_fitments_listing_id_fkey FOREIGN KEY (listing_id) REFERENCES public.listings(id) ON DELETE CASCADE;
alter table public.listing_fitments add constraint listing_fitments_make_bounds CHECK (char_length(make) >= 1 AND char_length(make) <= 60);
alter table public.listing_fitments add constraint listing_fitments_model_bounds CHECK (char_length(model) >= 1 AND char_length(model) <= 80);
alter table public.listing_fitments add constraint listing_fitments_pkey PRIMARY KEY (id);
alter table public.listing_fitments add constraint listing_fitments_year_end_sane CHECK (year_end IS NULL OR year_end >= 1930 AND year_end <= 2035);
alter table public.listing_fitments add constraint listing_fitments_year_order CHECK (year_start IS NULL OR year_end IS NULL OR year_end >= year_start);
alter table public.listing_fitments add constraint listing_fitments_year_start_sane CHECK (year_start IS NULL OR year_start >= 1930 AND year_start <= 2035);

-- Indexes
CREATE UNIQUE INDEX listing_fitments_claim_uniq ON public.listing_fitments USING btree (listing_id, lower(make), lower(model), COALESCE(year_start, 0), COALESCE(year_end, 9999));
CREATE INDEX listing_fitments_listing_idx ON public.listing_fitments USING btree (listing_id);
CREATE INDEX listing_fitments_vehicle_idx ON public.listing_fitments USING btree (lower(make), lower(model));

-- Grants
grant all on table public.listing_fitments to anon;
grant all on table public.listing_fitments to authenticated;
grant all on table public.listing_fitments to service_role;
